from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class RADParametersInterface(BaseClToolInterface):
    OPERATION = 'changeradparams'

    def change_bts_rad_parameters(self, params, timeout='15min', **kwargs):
        """Change RAD parameters.

        :param string params: RAD parameters e.g. 210:5:RD_Telecom

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: Changes will be lost after a BTS reset. For eNB version  FL00_FSM3_9999_150918_025203 and higher,
        parameter ID is needed instead of parameter or domain name e.g. 210:5:4. Refer to BTSCommandlineTools wiki for the ID of a parameter
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'params': params}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation=RADParametersInterface.OPERATION, params=params,
                                               trs_ip=ne, flags=flags)

    def change_bts_rad_parameters_permanently(self, params, timeout='15min', **kwargs):
        """Change RAD parameters and make them permanent.

        :param string params: RAD parameters e.g. 210:5:RD_Telecom

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: Changes will persist after a BTS reset. For eNB version  FL00_FSM3_9999_150918_025203 and higher,
        parameter ID is needed instead of parameter or domain name e.g. 210:5:4. Refer to BTSCommandlineTools wiki for the ID of a parameter
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'params': params}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['permanent']
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation=RADParametersInterface.OPERATION, params=params,
                                               trs_ip=ne, flags=flags)

    def change_bts_rad_parameters_with_overreset(self, params, timeout='15min', **kwargs):
        """Change RAD parameters with overreset. Persistent change over one reset

        :param string params: RAD parameters e.g. 210:5:RD_Telecom

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: For eNB version  FL00_FSM3_9999_150918_025203 and higher,
        parameter ID is needed instead of parameter or domain name e.g. 210:5:4. Refer to BTSCommandlineTools wiki for the ID of a parameter
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'params': params}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['overreset']
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation=RADParametersInterface.OPERATION, params=params,
                                               trs_ip=ne, flags=flags)

    def reset_bts_rad_parameters(self, params=None, timeout='15min', **kwargs):
        """ Reset RAD specified parameter to default.

        :param string params: Rad Parameters e.g. RD_Telecom

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: Keyword will reset all RAD parameters if params is not specified. For eNB version  FL00_FSM3_9999_150918_025203 and higher,
        parameter ID is needed instead of parameter or domain name e.g. 210:4. Refer to BTSCommandlineTools wiki for the ID of a parameter
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        parameters = {'ne': ne, 'pw': pw}
        if params is not None:
            parameters['params'] = params
        flags = ['defaults']
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation=RADParametersInterface.OPERATION, params=parameters,
                                               trs_ip=ne, flags=flags)

    def get_bts_rad_parameters(self, btsswsc, timeout='15min', **kwargs):
        """Get bts rad parameter

        :param string btsswsc: BTS SW domain e.g. BSTAT. May include a specific parameter of a SW domain e.g BSTAT_PrintTechrep

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: May get all R&D parameters of a specified SW Domain e.g. BSTAT or
               a specific parameter of a specified SW Domain e.g.BSTAT_PrintTechrep
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'btsswsc': btsswsc, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='getradparams', params=params, trs_ip=ne, flags=flags)
